), inserted AS (
  INSERT INTO market_observations (company_id, import_batch_id, metric_key, period_kind, period_start, period_end, observation_date, target_period, comparison_period_start, comparison_period_end, value, unit, source_value, source_unit, source_name, source_locator, source_label, basis, statement_scope, capture_method, capture_method_original, status, verification_status, published_on, published_at, retrieved_on, retrieved_at, content_fingerprint)
  SELECT company_id, batch.import_batch_id, metric_key, period_kind, period_start, period_end, observation_date, target_period, comparison_period_start, comparison_period_end, value, unit, source_value, source_unit, source_name, source_locator, source_label, basis, statement_scope, capture_method, capture_method_original, status, verification_status, published_on, published_at, retrieved_on, retrieved_at, content_fingerprint
  FROM input CROSS JOIN batch
  ON CONFLICT (content_fingerprint) DO NOTHING
  RETURNING id
)
SELECT (SELECT import_batch_id FROM batch) AS import_batch_id, (SELECT count(*) FROM input) AS input_rows, (SELECT count(*) FROM inserted) AS inserted_rows, (SELECT count(*) FROM input) - (SELECT count(*) FROM inserted) AS skipped_duplicates;
COMMIT;
